def clamp(x, lo, hi):
    """x を lo 以上 hi 以下の範囲に収めて返す。

    x が hi より大きければ hi、lo より小さければ lo を返す。
    """
    return max(lo, min(x, hi))

# 値 x を [lo, hi] の範囲に制限する（範囲外なら近い方の端に丸める）
def clamp(x, lo, hi):
    # まず上限 hi で抑え、次に下限 lo で持ち上げる
    return max(lo, min(x, hi))

def clamp(x, lo, hi):
    """x を lo 以上 hi 以下に収めて返す。"""
    return min(max(x, lo), hi)

def clamp(x, lo, hi):
    """x を [lo, hi] の範囲に収める。"""
    if lo > hi:
        raise ValueError('lo must be <= hi')
    return max(lo, min(x, hi))

def clamp(x, lo, hi):
    # x と lo, hi のうち最大の値を返す
    return max(lo, min(x, hi))
